def reachableCount(n, edges, restricted):
    blocked = [False] * n
    for x in restricted:
        blocked[x] = True
    adj = [[] for _ in range(n)]
    for a, b in edges:
        if not blocked[a] and not blocked[b]:
            adj[a].append(b)
            adj[b].append(a)
    seen = [False] * n
    seen[0] = True
    stack = [0]
    count = 0
    while stack:
        u = stack.pop()
        count += 1
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                stack.append(v)
    return count
